// Temporary format probe while the native camera bridges are rendering.
const {chromium}=require('playwright'),fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {execFileSync}=require('node:child_process'),out=process.env.REVIEW_OUTPUT;fs.mkdirSync(out,{recursive:true});
const report={commit:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),passed:false,errors:[],screenshots:[],checks:[],scope:'fixed-loop MSE format probe; no camera-transition claim'};let browser;
function record(view){const data=fs.readFileSync('website/assets/camera54/'+view+'.mp4'),starts=[];for(let p=0;p<data.length;){if(data.toString('ascii',p+4,p+8)==='moof')starts.push(p);p+=data.readUInt32BE(p);}return {src:view+'.mp4',init_bytes:starts[0],segments:starts.map((p,i)=>({offset:p,bytes:(starts[i+1]||data.length)-p,frames:5}))};}
(async()=>{try{browser=await chromium.launch({channel:'chrome'});const page=await browser.newPage({viewport:{width:1440,height:900},reducedMotion:'reduce'});page.on('pageerror',e=>report.errors.push(e.message));
await page.route('**/assets/camera54/manifest.json',route=>route.fulfill({json:{codec:'avc1.64001f',views:{near:record('near'),middle:record('middle')},bridges:{'near-middle':[],'middle-near':[]}}}));
await page.goto('http://127.0.0.1:8787/distance-study.html');await page.waitForFunction(()=>window.distanceStudy?.state.ready||window.distanceStudy?.state.error,null,{timeout:30000});let s=await page.evaluate(()=>window.distanceStudy.state);assert(!s.error,JSON.stringify(s));await page.locator('#distance-play').click();await page.waitForFunction(()=>document.querySelector('video').currentTime>=12,null,{timeout:20000});s=await page.evaluate(()=>window.distanceStudy.state);assert(!s.error,JSON.stringify(s));assert.equal(s.waits.length,0,JSON.stringify(s));assert.equal(String(s.sourceChanges),'1');report.checks.push(s);await page.screenshot({path:path.join(out,'stream-smoke.jpg')});report.screenshots.push({file:'stream-smoke.jpg'});report.passed=true;
}catch(e){report.errors.push(e.stack||String(e));process.exitCode=1;}finally{fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));await browser?.close();}})();
